// ============================================================================
// SHA3_apb: APB4 register wrapper around SHA3_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/SHA3.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/SHA3.md
// ============================================================================
module SHA3_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq
);
  localparam logic [31:0] ID_VALUE = 32'h53330100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [13:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd14) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_start;
  logic [2:0]    c_mode;
  logic          c_in_valid;
  logic [63:0]   c_in_data;
  logic [3:0]    c_in_bytes;
  logic          c_in_last;
  logic          c_in_ready;
  logic          c_out_valid;
  logic [63:0]   c_out_data;
  logic          c_out_last;
  logic          c_out_ready;
  logic          c_busy;
  logic          c_done;
  logic          c_err;
  SHA3_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .start(c_start),
    .mode(c_mode),
    .in_valid(c_in_valid),
    .in_data(c_in_data),
    .in_bytes(c_in_bytes),
    .in_last(c_in_last),
    .in_ready(c_in_ready),
    .out_valid(c_out_valid),
    .out_data(c_out_data),
    .out_last(c_out_last),
    .out_ready(c_out_ready),
    .busy(c_busy),
    .done(c_done),
    .err(c_err)
  );

  // ---------------- registers ----------------
  logic [4:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [2:0] r_CTRL;   // 12'h014 CTRL
  logic [0:0] p_CMD;   // 12'h018 CMD (pulses)
  logic [31:0] h_MSG0;   // 12'h01C MSG0 holding register
  logic [31:0] h_MSG1;   // 12'h020 MSG1 holding register
  logic [4:0] h_MSG2;   // 12'h024 MSG2 holding register
  logic [31:0] h_DIGEST0;   // 12'h028 DIGEST0 holding register
  logic [31:0] h_DIGEST1;   // 12'h02C DIGEST1 holding register
  logic [0:0] h_DIGEST2;   // 12'h030 DIGEST2 holding register
  logic full_MSG;
  logic avail_DIGEST;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 3'h1;
      p_CMD <= '0;
      h_MSG0 <= '0;
      h_MSG1 <= '0;
      h_MSG2 <= '0;
      h_DIGEST0 <= '0;
      h_DIGEST1 <= '0;
      h_DIGEST2 <= '0;
      full_MSG <= 1'b0;
      avail_DIGEST <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[4:0] & wmask[4:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[2:0]) | (PWDATA[2:0] & wmask[2:0]);
      p_CMD <= (wr && hit[6]) ? PWDATA[0:0] & wmask[0:0] : '0;
      if (wr && hit[7] && !full_MSG) h_MSG0 <= (h_MSG0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8] && !full_MSG) h_MSG1 <= (h_MSG1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9] && !full_MSG) h_MSG2 <= (h_MSG2 & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[9] && !full_MSG) full_MSG <= 1'b1;
      else if (full_MSG && c_in_ready) full_MSG <= 1'b0;
      if (c_out_valid && (!avail_DIGEST || (rd && hit[12]))) begin
        h_DIGEST0[31:0] <= c_out_data[31:0];
        h_DIGEST1[31:0] <= c_out_data[63:32];
        h_DIGEST2 <= c_out_last;
        avail_DIGEST <= 1'b1;
      end else if (rd && hit[12]) avail_DIGEST <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_mode = r_CTRL[2:0];
  assign c_start = p_CMD;
  assign c_in_data[31:0] = h_MSG0[31:0];
  assign c_in_data[63:32] = h_MSG1[31:0];
  assign c_in_bytes[3:0] = h_MSG2[3:0];
  assign c_in_last = h_MSG2[4:4];
  assign c_in_valid = full_MSG;
  assign c_out_ready = ~avail_DIGEST | (rd & hit[12]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_done;
    irq_set[1] = c_err;
    irq_set[2] = full_MSG & c_in_ready;
    irq_set[3] = wr & (hit[7] | hit[8] | hit[9]) & full_MSG;
    irq_set[4] = c_out_valid & (~avail_DIGEST | (rd & hit[12]));
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_DIGEST, full_MSG};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd7: apb_rdata = 32'(h_MSG0);
      10'd8: apb_rdata = 32'(h_MSG1);
      10'd9: apb_rdata = 32'(h_MSG2);
      10'd10: apb_rdata = 32'(h_DIGEST0);
      10'd11: apb_rdata = 32'(h_DIGEST1);
      10'd12: apb_rdata = 32'(h_DIGEST2);
      10'd13: apb_rdata = 32'({c_busy});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
